import * as fs from 'node:fs';import {join} from 'node:path';
const [dist,root]=process.argv.slice(2);const g=await import(dist+'/goalplan.js');
const p={objective:'o',slug:'demo',workPhases:[],criteria:[],host:{armed:false,armedAt:null,source:'none'}};
const cases=[];const add=(id,raw,setup,changed)=>{const cwd=fs.mkdtempSync(join(root,'oracle-')),dir=join(cwd,'.codexclaw/goalplans/demo');fs.mkdirSync(dir,{recursive:true});if(raw!==undefined)fs.writeFileSync(join(dir,'goalplan.json'),raw);setup?.(cwd,dir);let result;try{result=g.readGoalplanDetailed(cwd,'demo')}catch(e){result={thrown:e.message}};let lock;try{lock=g.withGoalplanWriteLock(cwd,'demo',()=> 'entered',{retryDelaysMs:[],now:()=> '2026-01-01T00:00:00.000Z'})}catch(e){lock={thrown:e.message}};const norm=v=>JSON.parse(JSON.stringify(v).replaceAll(cwd,'${WS}').replaceAll('.codexclaw','.crw'));cases.push({id,raw:raw??null,read:norm(result),lock:norm(lock),classification:changed?'intentionally-changed':'identical',reason:changed??undefined});};
add('absent',undefined);add('valid',JSON.stringify(p));
for(const [id,value] of Object.entries({root_array:[],root_null:null,objective:{...p,objective:3},slug:{...p,slug:'other'},future:{...p,schemaVersion:4},phases:{...p,workPhases:null},phase_title:{...p,workPhases:[{id:'w'}]},phase_dep:{...p,workPhases:[{id:'w',title:'w',dependsOn:null}]},phase_await:{...p,workPhases:[{id:'w',title:'w',awaitsDecision:[null]}]},task_dep:{...p,workPhases:[{id:'w',title:'w',tasks:[{id:'t',title:'t',dependsOn:[1]}]}]},criteria:{...p,criteria:null},criterion_scenario:{...p,criteria:[{id:'c'}]},criterion_id:{...p,criteria:[{scenario:'s'}]},decisions:{...p,decisions:null},steering_shape:{...p,steeringLog:{}},steering_entry:{...p,steeringLog:[{}]}}))add(id,JSON.stringify(value));
add('invalid_json','{not-json');add('trailing_json',JSON.stringify(p)+'{}');
add('lone_surrogate',JSON.stringify(p).replace('"o"','"\\ud800"'),undefined,'data loss: refuse before an escaped lone surrogate becomes U+FFFD');
add('plan_symlink',undefined,(cwd,dir)=>{fs.writeFileSync(join(cwd,'outside'),JSON.stringify(p));fs.symlinkSync(join(cwd,'outside'),join(dir,'goalplan.json'));},'security: refuse non-following file access');
add('dangling_plan',undefined,(cwd,dir)=>fs.symlinkSync(join(cwd,'missing'),join(dir,'goalplan.json')),'security: dangling link refused instead of absent');
add('dangling_root',undefined,(cwd)=>{fs.rmSync(join(cwd,'.codexclaw'),{recursive:true});fs.symlinkSync(join(cwd,'missing'),join(cwd,'.codexclaw'));},'security: dangling ancestor refused instead of absent');
add('lock_symlink',JSON.stringify(p),(cwd,dir)=>{fs.mkdirSync(join(cwd,'outside'));fs.writeFileSync(join(cwd,'outside/owner.json'),'secret');fs.symlinkSync(join(cwd,'outside'),join(dir,g.GOALPLAN_LOCK_DIR));},'security: refuse linked lock and never read its owner');
add('owner_symlink',JSON.stringify(p),(cwd,dir)=>{fs.mkdirSync(join(dir,g.GOALPLAN_LOCK_DIR));fs.writeFileSync(join(cwd,'outside'),'secret');fs.symlinkSync(join(cwd,'outside'),join(dir,g.GOALPLAN_LOCK_DIR,g.GOALPLAN_LOCK_OWNER_FILE));},'security: owner diagnostic must not read outside');
console.log(JSON.stringify({oracle:'CXC v0.2.40 3c1459ac',cases},null,2));
